param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$OutDir)
Add-Type -AssemblyName System.Drawing
$source = @'
using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Drawing.Text;
public static class RRScenes {
 const int W=1080,H=1350;
 static Color Pink=Color.FromArgb(239,61,145), Pale=Color.FromArgb(255,212,232), Gold=Color.FromArgb(245,198,107), White=Color.FromArgb(255,249,252);
 static Font F(float s,FontStyle st=FontStyle.Regular){return new Font("Segoe UI",s,st,GraphicsUnit.Pixel);}
 static void Text(Graphics g,string s,float x,float y,float size,Color c,FontStyle st=FontStyle.Regular){using(var b=new SolidBrush(c))g.DrawString(s,F(size,st),b,x,y);}
 static void Center(Graphics g,string s,float x,float y,float size,Color c,FontStyle st=FontStyle.Regular){using(var f=F(size,st))using(var b=new SolidBrush(c)){var z=g.MeasureString(s,f);g.DrawString(s,f,b,x-z.Width/2,y);}}
 static GraphicsPath Round(float x,float y,float w,float h,float r){var p=new GraphicsPath();p.AddArc(x,y,r,r,180,90);p.AddArc(x+w-r,y,r,r,270,90);p.AddArc(x+w-r,y+h-r,r,r,0,90);p.AddArc(x,y+h-r,r,r,90,90);p.CloseFigure();return p;}
 static void Card(Graphics g,float x,float y,float w,float h,Color color){using(var p=Round(x,y,w,h,22))using(var b=new SolidBrush(Color.FromArgb(145,3,4,17)))g.FillPath(b,p);using(var p=Round(x,y-10,w,h,22))using(var b=new LinearGradientBrush(new RectangleF(x,y-10,w,h),Color.FromArgb(255,39,29,57),Color.FromArgb(255,22,20,39),90f))using(var pen=new Pen(Color.FromArgb(100,Pink),2)){g.FillPath(b,p);g.DrawPath(pen,p);}}
 static void Ball(Graphics g,float x,float y,float r){using(var path=new GraphicsPath()){path.AddEllipse(x-r,y-r,2*r,2*r);using(var b=new PathGradientBrush(path)){b.CenterPoint=new PointF(x-r*.28f,y-r*.32f);b.CenterColor=Color.FromArgb(255,255,196,223);b.SurroundColors=new[]{Color.FromArgb(255,108,17,74)};g.FillPath(b,path);}}using(var p=new Pen(Color.FromArgb(225,255,231,243),4)){p.DashPattern=new float[]{4,5};g.DrawBezier(p,x-r*.52f,y-r*.54f,x-r*.05f,y-r*.88f,x+r*.13f,y+r*.24f,x+r*.55f,y+r*.53f);}using(var p=new Pen(Color.FromArgb(90,255,255,255),2))g.DrawEllipse(p,x-r,y-r,2*r,2*r);using(var b=new SolidBrush(Color.FromArgb(72,255,255,255)))g.FillEllipse(b,x-r*.54f,y-r*.62f,r*.44f,r*.22f);}
 static Bitmap Base(string kicker,string[] title,string[] desc,int n){var b=new Bitmap(W,H,PixelFormat.Format24bppRgb);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.TextRenderingHint=TextRenderingHint.ClearTypeGridFit;using(var br=new LinearGradientBrush(new Rectangle(0,0,W,H),Color.FromArgb(20,13,41),Color.FromArgb(16,27,56),135))g.FillRectangle(br,0,0,W,H);using(var br=new SolidBrush(Color.FromArgb(19,239,61,145)))g.FillEllipse(br,650,100,740,600);using(var br=new SolidBrush(Color.FromArgb(15,86,124,234)))g.FillEllipse(br,-300,820,850,670);for(int x=35;x<W;x+=52)for(int y=150;y<H;y+=52)using(var p=new Pen(Color.FromArgb(10,211,176,235),1))g.DrawLine(p,x,y,x,y+1);using(var p=new Pen(Color.FromArgb(80,255,255,255),2))g.DrawLine(p,64,62,1016,62);using(var p=new Pen(Pink,3))g.DrawLine(p,64,62,64+952*n/7,62);Text(g,kicker.ToUpper(),72,91,18,Pale,FontStyle.Bold);for(int i=0;i<title.Length;i++)Text(g,title[i],68,170+i*75,58,White,FontStyle.Bold);for(int i=0;i<desc.Length;i++)Text(g,desc[i],72,340+(title.Length-1)*75+i*38,23,Color.FromArgb(255,201,193,214));Text(g,"PRESSURE PLAYBOOK  |  SupeRR SELECTOR",72,1280,15,Color.FromArgb(255,216,201,223),FontStyle.Bold);Text(g,n.ToString("00")+" / 07",938,1280,15,Color.FromArgb(255,216,201,223),FontStyle.Bold);}return b;}
 static void Pitch(Graphics g){using(var b=new SolidBrush(Color.FromArgb(80,239,61,145)))g.FillEllipse(b,100,825,880,300);using(var p=new Pen(Color.FromArgb(150,242,141,195),3))g.DrawEllipse(p,100,825,880,300);using(var b=new SolidBrush(Color.FromArgb(90,60,90,151)))g.FillEllipse(b,190,863,700,216);using(var b=new SolidBrush(Color.FromArgb(80,53,121,111)))g.FillEllipse(b,300,895,480,150);using(var p=new Pen(Color.FromArgb(200,245,226,190),4)){g.DrawLine(p,505,888,520,1062);p.DashPattern=new float[]{5,5};g.DrawLine(p,512,960,522,1025);}}
 static void Cover(Bitmap b,int idx,string root){using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;string[] names={"dashboard-home-clean.jpg","batter-rankings-clean.jpg"};for(int z=0;z<2;z++){using(var im=Image.FromFile(System.IO.Path.Combine(root,"screenshots",names[z]))){float x=z==0?80:510,y=z==0?550:935,w=z==0?920:490,h=z==0?570:300;Card(g,x,y,w,h,Color.FromArgb(255,28,25,45));PointF[] pts={new PointF(x+22,y+8),new PointF(x+w-22,y+z*10),new PointF(x+10,y+h-10)};g.DrawImage(im,pts);using(var p=new Pen(Color.FromArgb(205,255,255,255),2))g.DrawPolygon(p,new[]{pts[0],pts[1],new PointF(x+w-10,y+h-12),pts[2]});}}}}
 static void One(int n,string root,string outDir){string[][] title={new[]{"Find the signal","in the pressure."},new[]{"A decision-support","lens for cricket."},new[]{"Pressure is a situation.","Clutch is a comparison."},new[]{"Three checks.","One readable signal."},new[]{"Explore the evidence."},new[]{"Useful signal.","Honest limits."},new[]{"A small project,","built around better questions."}};string[][] desc={new[]{"Who performs above their own baseline","when a T20 game gets tight?"},new[]{"Made for Unstop's SupeRR Selector Season 2","challenge for the Rajasthan Royals."},new[]{"Compare each player's pressure output with their own","ordinary T20 and T20I baseline."},new[]{"Tag the game state. Compare with self.","Then account for sample size and repeat evidence."},new[]{"Search, filter, inspect profiles and compare","a shortlist in the interactive player lab."},new[]{"A transparent shortlist, not a promise of future results.","Role fit, availability and auction context still matter."},new[]{"Created for Unstop's SupeRR Selector Season 2","challenge for the Rajasthan Royals."}};
 using(Bitmap b=Base(new[]{"The moment matters","The project","What it does","How it works","The working dashboard","Built with care","Thank you"}[n-1],title[n-1],desc[n-1],n))using(Graphics g=Graphics.FromImage(b)){
 g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;
 if(n==1){Pitch(g);using(var p=new Pen(Color.FromArgb(180,255,137,191),4)){p.DashPattern=new float[]{8,10};g.DrawBezier(p,170,760,355,560,570,590,755,738);}using(var p=new Pen(Color.FromArgb(210,255,215,231),3))g.DrawPolygon(p,new[]{new Point(180,760),new Point(210,650),new Point(245,760)});}
 else if(n==2){Ball(g,825,676,105);Card(g,160,622,760,315,Color.FromArgb(255,28,22,46));using(var br=new LinearGradientBrush(new Rectangle(184,652,712,75),Color.FromArgb(255,255,131,186),Pink,0f))g.FillRectangle(br,184,652,712,75);Center(g,"SupeRR SELECTOR",540,665,33,White,FontStyle.Bold);Center(g,"DATA   ·   EVIDENCE   ·   CRICKET",540,783,20,Color.FromArgb(255,206,195,218),FontStyle.Bold);using(var p=new Pen(Gold,4))g.DrawLine(p,370,870,710,870);}
 else if(n==3){Card(g,85,644,430,300,Color.FromArgb(255,29,24,48));Card(g,560,644,430,300,Color.FromArgb(255,38,20,45));Center(g,"USUAL BASELINE",300,720,22,Color.FromArgb(255,191,181,202),FontStyle.Bold);Center(g,"PLAYER",300,790,51,White,FontStyle.Bold);Center(g,"PRESSURE OUTPUT",775,720,22,Color.FromArgb(255,248,181,213),FontStyle.Bold);Center(g,"PLAYER",775,790,51,White,FontStyle.Bold);using(var p=new Pen(Pink,6))g.DrawLine(p,400,893,680,893);Ball(g,880,599,45);}
 else if(n==4){string[] labels={"01  TAG THE MOMENT","02  COMPARE WITH SELF","03  CHECK THE EVIDENCE"};string[][] body={new[]{"Late overs or a","demanding chase.","Rules are set before the ball."},new[]{"Batting and bowling","scored separately.","Each player is their own control."},new[]{"Screen thin samples.","Reward repeat evidence.","Exposure adjusts the score."}};for(int i=0;i<3;i++){float x=70+i*330,y=650+(i==1?30:0);Card(g,x,y,315,300,Color.FromArgb(255,32,25,51));using(var br=new LinearGradientBrush(new Rectangle((int)x,(int)y,315,7),Pink,Gold,0f))g.FillRectangle(br,x,y,315,7);Text(g,labels[i],x+22,y+40,17,Pale,FontStyle.Bold);for(int j=0;j<3;j++)Text(g,body[i][j],x+22,y+113+j*38,19,Color.FromArgb(255,205,195,215));}}
 else if(n==5){Cover(b,n,root);}
 else if(n==6){Pitch(g);Point[] pts={new Point(145,820),new Point(267,734),new Point(390,781),new Point(514,635),new Point(640,736),new Point(772,670),new Point(910,816)};using(var fill=new SolidBrush(Color.FromArgb(45,239,61,145)))using(var path=new GraphicsPath()){path.AddPolygon(new[]{pts[0],pts[1],pts[2],pts[3],pts[4],pts[5],pts[6],new Point(910,820),new Point(145,820)});g.FillPath(fill,path);}using(var p=new Pen(Gold,5)){g.DrawLines(p,pts);foreach(Point q in pts)g.FillEllipse(Brushes.White,q.X-7,q.Y-7,14,14);}Card(g,145,950,790,84,Color.FromArgb(255,32,24,48));Center(g,"INDEPENDENT PROJECT  ·  NO OFFICIAL RR AFFILIATION",540,976,19,Color.FromArgb(255,238,228,242),FontStyle.Bold);}
 else {Ball(g,824,665,101);Card(g,160,710,760,330,Color.FromArgb(255,29,23,46));Center(g,"THANKS FOR WATCHING",540,752,23,Gold,FontStyle.Bold);Center(g,"Explore the live dashboard",540,835,34,White,FontStyle.Bold);Center(g,"pressure-selector-rr.onrender.com",540,907,23,Pale);using(var p=new Pen(Gold,4))g.DrawLine(p,430,980,650,980);}
 b.Save(System.IO.Path.Combine(outDir,"scene-"+n.ToString("00")+".png"),ImageFormat.Png);
 }}
 public static void Render(string root,string outDir){for(int i=1;i<=7;i++)One(i,root,outDir);using(Bitmap ball=new Bitmap(220,220,PixelFormat.Format32bppArgb))using(Graphics g=Graphics.FromImage(ball)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);Ball(g,110,110,98);ball.Save(System.IO.Path.Combine(outDir,"cricket-ball.png"),ImageFormat.Png);}}
}
'@
Add-Type -TypeDefinition $source -ReferencedAssemblies System.Drawing
[RRScenes]::Render((Resolve-Path $Root).Path,(Resolve-Path $OutDir).Path)






